var MODEL_EXTS=["glb","gltf","fbx","vrm","stl","obj"];
function sniffModelExt(bytes){
  var head=new TextDecoder().decode(bytes.subarray(0,64));
  if(head.startsWith("glTF"))return "glb";
  if(head.startsWith("Kaydara FBX Binary")||/^\s*;\s*FBX/.test(head))return "fbx";
  if(/^\s*\{/.test(head))return "gltf";
  var text=new TextDecoder().decode(bytes.subarray(0,2048));
  if(/^\s*solid\b/.test(text)&&/\bfacet\b/.test(text))return "stl";
  if(/^\s*v\s+-?[\d.]/m.test(text)&&/^\s*(#|(v|vn|vt|f|o|g|s|mtllib|usemtl)\b)/.test(text))return "obj";
  return "stl";
}
function openModelBytes(data,name){
  var bytes=data instanceof Uint8Array?data:new Uint8Array(data);
  name=name||"model";
  var ext=(name.split(".").pop()||"").toLowerCase();
  if(MODEL_EXTS.indexOf(ext)===-1)name=name+"."+sniffModelExt(bytes);
  Ia(new File([bytes],name));
}

/* Hook up OS file opening only after every <script> (incl. obj-loader.js) has run. */
function initExternalOpen(){
/* Electron: main process passes file paths (double-click, "Open with", CLI args). */
if(window.viewerAPI){
  var loadDesktopPath=async function(p){
    try{
      var r=await window.viewerAPI.readFile(p);
      openModelBytes(r.data,r.name);
    }catch(err){
      console.error("Failed to open file",err);
      alert("Could not open file: "+p);
    }
  };
  window.viewerAPI.onOpenFile(loadDesktopPath);
  window.viewerAPI.ready().then(function(paths){
    if(paths&&paths.length)loadDesktopPath(paths[paths.length-1]);
  });
}

/* Android (Capacitor): ACTION_VIEW intents arrive as content:// or file:// URIs. */
(function(){
  var cap=window.Capacitor;
  if(!cap||!cap.isNativePlatform||!cap.isNativePlatform())return;
  /* Android's picker can't map .glb/.fbx/.vrm extensions to MIME types, so let it show everything. */
  Mp.removeAttribute("accept");
  var lastUri=null;
  function nameFromUri(uri){
    try{
      var seg=decodeURIComponent(uri.split("?")[0]).split(/[\/:]/).pop();
      return seg||"model";
    }catch(e){return "model";}
  }
  async function openUri(uri){
    if(!uri||uri===lastUri)return;
    lastUri=uri;setTimeout(function(){lastUri=null;},2000);
    try{
      var res=await fetch(cap.convertFileSrc(uri));
      if(!res.ok)throw new Error("HTTP "+res.status);
      openModelBytes(new Uint8Array(await res.arrayBuffer()),nameFromUri(uri));
    }catch(err){
      console.error("Failed to open shared file",err);
      alert("Could not open file.");
    }
  }
  var App=cap.Plugins&&cap.Plugins.App;
  if(!App){console.warn("@capacitor/app plugin not available");return;}
  App.addListener("appUrlOpen",function(e){openUri(e&&e.url);});
  App.getLaunchUrl().then(function(r){if(r&&r.url)openUri(r.url);}).catch(function(){});
})();
}
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",initExternalOpen);else initExternalOpen();

